<?php
namespace App\Http\Controllers;
use App\Models\Lease; use App\Models\Property; use App\Models\Tenant; use App\Models\Unit; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class OnboardingController extends Controller { private array $headers=['property_code','property_name','property_type','county','town','address','latitude','longitude','floors','unit_number','unit_type','bedrooms','bathrooms','floor','monthly_rent','deposit','unit_status','tenant_name','tenant_id_number','tenant_phone','tenant_email']; private function authorizeOwner(): void { abort_unless(in_array(auth()->user()?->role,['Owner','Super Admin'],true),403); } public function index(){ $this->authorizeOwner(); return view('onboarding.index'); } public function template(){ $this->authorizeOwner(); return response(implode(',', $this->headers)."\n".'APT-001,Sunset Apartments,Apartment,Nairobi,Nairobi,Example Road 1,-1.286389,36.817223,6,A1,1 Bedroom,1,1,1,25000,25000,Occupied,Jane Wanjiku,12345678,0712345678,jane@example.com' . "\n", 200, ['Content-Type'=>'text/csv','Content-Disposition'=>'attachment; filename=kwetu-onboarding-template.csv']); } public function store(Request $request){ $this->authorizeOwner(); $request->validate(['file'=>['required','file','mimes:csv,txt','max:5120']]); $rows=array_map('str_getcsv', file($request->file('file')->getRealPath(), FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES)); abort_if(count($rows)<2,422,'The CSV needs a header and at least one data row.'); $headers=array_map(fn($value)=>Str::lower(trim(preg_replace('/^\xEF\xBB\xBF/', '', $value))),array_shift($rows)); abort_unless($headers===$this->headers,422,'Use the downloadable template and keep its headers unchanged.'); $org=auth()->user()->organization_id; abort_unless($org,422,'Your account needs an organization before importing.'); $created=['properties'=>0,'units'=>0,'tenants'=>0]; try { DB::transaction(function() use($rows,$headers,$org,&$created){ foreach($rows as $index=>$row){ $data=array_combine($headers,array_pad($row,count($headers),'')); if(!$data || !trim($data['property_code']) || !trim($data['unit_number'])) throw new \RuntimeException('Row '.($index+2).' needs a property code and unit number.'); foreach(['latitude','longitude','monthly_rent'] as $field) if(!is_numeric($data[$field])) throw new \RuntimeException('Row '.($index+2).' has an invalid '.$field.'.'); $property=Property::firstOrNew(['code'=>trim($data['property_code'])]); if($property->exists && $property->organization_id!==$org) throw new \RuntimeException('Row '.($index+2).' uses a property code owned by another organization.'); if(!$property->exists){ $property->fill(['organization_id'=>$org,'name'=>$data['property_name'],'type'=>$data['property_type'] ?: 'Apartment','county'=>$data['county'],'town'=>$data['town'],'address'=>$data['address'],'latitude'=>$data['latitude'],'longitude'=>$data['longitude'],'floors'=>(int)($data['floors'] ?: 1),'status'=>'Active','verification_status'=>'Pending'])->save(); $created['properties']++; } $unit=Unit::firstOrNew(['property_id'=>$property->id,'unit_number'=>trim($data['unit_number'])]); $new=!$unit->exists; $status=in_array($data['unit_status'],['Vacant','Occupied','Reserved','Maintenance'])?$data['unit_status']:'Vacant'; $unit->fill(['unit_type'=>$data['unit_type'] ?: 'Unit','bedrooms'=>(int)($data['bedrooms'] ?: 0),'bathrooms'=>(int)($data['bathrooms'] ?: 1),'floor'=>(int)($data['floor'] ?: 1),'monthly_rent'=>$data['monthly_rent'],'deposit'=>is_numeric($data['deposit'])?$data['deposit']:0,'status'=>$status])->save(); if($new)$created['units']++; if($status==='Occupied' && trim($data['tenant_name']) && trim($data['tenant_id_number']) && trim($data['tenant_phone'])){ $tenant=Tenant::firstOrCreate(['id_number'=>trim($data['tenant_id_number'])],['organization_id'=>$org,'full_name'=>$data['tenant_name'],'phone'=>$data['tenant_phone'],'email'=>$data['tenant_email'] ?: null,'gender'=>'Other','portal_token'=>Str::random(48)]); if($tenant->organization_id!==$org) throw new \RuntimeException('Row '.($index+2).' uses a tenant ID belonging to another organization.'); if($tenant->wasRecentlyCreated)$created['tenants']++; Lease::firstOrCreate(['tenant_id'=>$tenant->id,'unit_id'=>$unit->id,'status'=>'Active'],['organization_id'=>$org,'start_date'=>now()->toDateString(),'rent_amount'=>$unit->monthly_rent,'deposit_amount'=>$unit->deposit,'payment_frequency'=>'Monthly']); } } }); } catch (\RuntimeException $exception) { return back()->withErrors(['file'=>$exception->getMessage()]); } return back()->with('success', "Import complete: {$created['properties']} properties, {$created['units']} units, {$created['tenants']} tenants added."); } }
